    {
      "id": 1,
      "claim": "A concave spherical mirror obeys the mirror equation 1/f = 1/do + 1/di with f>0.",
      "evidence": "Standard optics relation for spherical mirrors (sign convention for real focus).",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "When the object is at infinity (do → ∞), the image distance di equals the focal length f.",
      "evidence": "Set 1/do → 0 in the mirror equation, giving 1/di = 1/f ⇒ di = f.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "For any finite object distance do > f, the image distance is di = f·do/(do – f); as do decreases toward f, di increases without bound.",
      "evidence": "Algebraic rearrangement of the mirror equation: di = (f·do)/(do – f). The denominator (do – f) → 0⁺ as do → f⁺, so di → +∞.",
      "weight": 0.30,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "The linear magnification magnitude is |m| = di/do = f/(do – f); as do → f⁺, |m| → ∞, so the image gets taller.",
      "evidence": "Definition of magnification for mirrors m = –di/do; substitute di from step 3.",
      "weight": 0.25,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Therefore, moving the object from far away toward the focal point makes the image move farther from the mirror and become taller.",
      "evidence": "Step 3 shows image distance increases; step 4 shows magnification increases.",
      "weight": 0.10,
      "depends_on": [3, 4]
    }
  ],
